class EditTimeDialogController{constructor($mdDialog,DispatchData,toastrService,job,time,title,fieldName,id){this._$mdDialog=$mdDialog;this._dispatchData=DispatchData;this._toastrService=toastrService;this._job=job;this._fieldName=fieldName;this.id=id;this.isLoading=false;this.time=new Date(time);this.title=title;this.message={hour:"Hour is required",minute:"Minute is required"}}async submit(time){try{this.isLoading=true;this._job.bulkJob?await this._dispatchData.updateBulkJobDetail(this._job.id,this._fieldName,time,this._job.charge,FirstName,ContactID):await this._dispatchData.updateJobDetail(this._job.id,this._fieldName,time,this._job.charge,FirstName,ContactID,this._job.preBook);let fieldName=this._fieldName.toLowerCase();let matchingField=Object.keys(this._job).find(key=>key.toLowerCase()===fieldName);if(matchingField){this._job[matchingField]=time}else{console.warn(`Field ${this._fieldName} not found in job object.`)}this._$mdDialog.hide()}catch(error){this._toastrService.showErrorToast(error.message)}finally{this.isLoading=false}}cancel(){this._$mdDialog.cancel()}}